function toast(msg){$('toast').textContent=msg;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast')?.classList.remove('visible'),3500);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(store));return true;}catch{storageOk=false;toast('浏览器存储不可用或已满，请导出备份；此次修改未保存。');return false;}}
function event(type,noteId){store.events.push({type,noteId,at:new Date().toISOString()});if(store.events.length>3000)store.events=store.events.slice(-3000);}
function math(el=document){if(window.renderMathInElement)window.renderMathInElement(el,{delimiters:[{left:'\\[',right:'\\]',display:true},{left:'\\(',right:'\\)',display:false},{left:'$$',right:'$$',display:true}],throwOnError:false,trust:false});}
const titles={home:'学习桌',lesson:'拍照讲题',notebook:'我的错题本',review:'复习计划',knowledge:'知识与卡片',insights:'学习报告',parent:'家长管理'};
function go(view){if(!$(view))return;document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==view);document.querySelectorAll('.nav').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('breadcrumb').innerHTML='我的学习空间 <i>/</i> '+titles[view];if(view==='notebook')renderNotes();if(view==='review')renderReview();if(view==='insights'||view==='parent')renderReport();if(view==='knowledge')renderKnowledge();window.scrollTo(0,0);location.hash=view;}
function empty(title,text){return '<div class="empty"><div class="symbol">✧</div><h3>'+esc(title)+'</h3><p>'+esc(text)+'</p><button class="secondary" data-go="home">去学习桌试一道样题 →</button></div>';}
